package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill; import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId; public final class DashEffectSpec implements EffectSpec{private final StableId effectId;private final int maximumDistance;private final MovementPolicies.PathPolicy pathPolicy;public DashEffectSpec(StableId id,int distance,MovementPolicies.PathPolicy policy){if(id==null||policy==null||distance<1)throw new IllegalArgumentException("invalid dash fields");effectId=id;maximumDistance=distance;pathPolicy=policy;}@Override public StableId effectId(){return effectId;}@Override public EffectFamily family(){return EffectFamily.MOVEMENT;}@Override public EffectVariantKey variantKey(){return EffectVariantKey.DASH;}public int maximumDistance(){return maximumDistance;}public MovementPolicies.PathPolicy pathPolicy(){return pathPolicy;}}
